  harness(on, liveSchedule(), { ...followingValkyries, ...colouredLogos })
  await start($)

  expect((await mountBand($, 46)).props?.flexDirection).not.toBe('column')
  expect((await mountBand($, 45)).props?.flexDirection).toBe('column')
